#!/usr/bin/env python3
"""markitai: write src/glyph_names/sorted_names.rs from the glyph list.

`glyph_to_unicode` binary-searches the glyph names in byte order. This script
reads every `    m.insert("NAME", 'CHAR');` line of src/glyph_names.rs, which
are the list of `build_glyph_to_unicode_map` and the overrides
`GLYPH_TO_UNICODE` inserts after it (both compiled only for tests), and writes
all names, each with its character, sorted by their bytes. A later insert of a
name replaces an earlier one, as it did in the map.

    python3 scripts/sorted_glyph_names.py          # rewrite the table
    python3 scripts/sorted_glyph_names.py --check  # exit 1 if it is stale

Paths are relative to the crate root, wherever the script is run from.
"""
import re
import sys
from pathlib import Path

CRATE = Path(__file__).resolve().parent.parent
SOURCE = CRATE / 'src/glyph_names.rs'
TABLE = CRATE / 'src/glyph_names/sorted_names.rs'
INSERT = re.compile(r"    m\.insert\(\"([A-Za-z0-9_]+)\", '([^'\\]|\\.[^']*)'\);")
SIMPLE_ESCAPES = {'n': '\n', 'r': '\r', 't': '\t', '\\': '\\', '0': '\0', "'": "'", '"': '"'}


def char_literal(text, line):
    """The character a Rust char literal's body stands for."""
    if not text.startswith('\\'):
        return text
    body = text[1:]
    if body in SIMPLE_ESCAPES:
        return SIMPLE_ESCAPES[body]
    escape = re.fullmatch(r'x([0-7][0-9A-Fa-f])', body) or re.fullmatch(r'u\{([0-9A-Fa-f]{1,6})\}', body)
    if not escape:
        sys.exit(f'unexpected character literal in {SOURCE.name}: {line!r}')
    return chr(int(escape.group(1), 16))


def listed_names():
    """The glyph list's characters by name, later inserts replacing earlier."""
    names = {}
    for line in SOURCE.read_text(encoding='utf-8').splitlines():
        if 'm.insert(' not in line:
            continue
        entry = INSERT.fullmatch(line)
        if not entry:
            sys.exit(f'unexpected insert in {SOURCE.name}: {line!r}')
        names[entry.group(1)] = char_literal(entry.group(2), line)
    if not names:
        sys.exit(f'no glyph list in {SOURCE.name}')
    return names


def render(names):
    rows = []
    for name in sorted(names, key=str.encode):
        code = ord(names[name])
        if code > 0xFFFF:
            sys.exit(f'{name} stands for U+{code:X}, outside the 16-bit table')
        rows.append(f"    (\"{name}\", '\\u{{{code:04x}}}'),\n")
    return (
        '// @generated by scripts/sorted_glyph_names.py from the glyph list in\n'
        '// src/glyph_names.rs (markitai); run it again after changing the list.\n'
        '\n'
        '/// Every glyph name with its character, in ascending byte order.\n'
        "pub(super) const SORTED_GLYPH_NAMES: &[(&str, char)] = &[\n"
        f"{''.join(rows)}"
        '];\n'
    )


def main():
    names = listed_names()
    text = render(names)
    if sys.argv[1:] == ['--check']:
        current = TABLE.read_text(encoding='utf-8') if TABLE.exists() else ''
        if current != text:
            sys.exit(f'{TABLE.relative_to(CRATE)} is stale; run scripts/sorted_glyph_names.py')
        print(f'{TABLE.relative_to(CRATE)} is current ({len(names)} names)')
    elif not sys.argv[1:]:
        TABLE.write_text(text, encoding='utf-8')
        print(f'wrote {TABLE.relative_to(CRATE)} ({len(names)} names)')
    else:
        sys.exit(__doc__)


if __name__ == '__main__':
    main()
